import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = false;
  bool _isLoadingMore = false;

  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadInitialPage();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _loadInitialPage() async {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository
        .fetchRates(const CurrencyPageRequest())
        .then((CurrencyPage page) {
      _allCurrencies = page.items;
      _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);

      _currentPage = page.page + 1;
      _hasMore = page.hasMore;
      _isLoadingMore = false;

      if (mounted) _fadeController.forward();

      currencyRepository.saveCurrencyList(_allCurrencies);
      return _allCurrencies;
    });
  }

  void _filterCurrencies(String query) {
    _searchQuery = query.toLowerCase();

    final List<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(_searchQuery) || currency.symbol.toLowerCase().contains(_searchQuery);
    }).toList(growable: false);

    _filteredCurrenciesNotifier.value = result;
  }

  void _refreshFiltered() {
    if (_searchQuery.isEmpty) {
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
    } else {
      final List<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
        return currency.name.toLowerCase().contains(_searchQuery) || currency.symbol.toLowerCase().contains(_searchQuery);
      }).toList(growable: false);

      _filteredCurrenciesNotifier.value = result;
    }
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final page = await currencyRepository.fetchRates(
      CurrencyPageRequest(page: _currentPage),
    );

    if (!mounted) return;

    setState(() {
      _allCurrencies.addAll(page.items);
      _currentPage = page.page + 1;
      _hasMore = page.hasMore;
      _isLoadingMore = false;
    });

    _refreshFiltered();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return Column(
                        children: [
                          if (_isLoadingMore) const Padding(
                            padding: EdgeInsets.symmetric(vertical: 12),
                            child: Center(child: CircularProgressIndicator()),
                          ),

                          Expanded(
                            child: ListView.builder(
                              itemCount: data.length,
                              itemBuilder: (BuildContext context, int index) {
                                final CurrencyModel currency = data[index];

                                return Padding(
                                  key: ValueKey(currency.id),
                                  padding: index == 0
                                      ? const EdgeInsets.only(top: 20)
                                      : const EdgeInsets.only(top: 10),
                                  child: CurrencyCard(model: currency),
                                );
                              },
                            ),
                          ),

                          if (_hasMore && !_isLoadingMore) Padding(
                            padding: const EdgeInsets.all(16),
                            child: Center(
                              child: ElevatedButton(
                                onPressed: _loadNextPage,
                                child: Text(context.loc.showMore),
                              ),
                            ),
                          ),
                        ],
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
